      backup_text =
        "type RGB = (red=Int, green=Int, blue=Int) in\n\
         type HSL = (hue=Float, saturation=Float, lightness=Float) in\n\
         type Color =\n\
         +RGB(RGB)\n\
         +RGBA(RGB, alpha=Float)\n\
         +OKLCH(l=Int, c=Float, h=Int)\n\
         +HSL(HSL)\n\
         +HSLA(HSL, alpha=Float)\n\
         +Named(String)  \n\
         in\n\
         let color_to_css_string : Color -> String = fun color -> case color \n\
         | RGB(r,g,b) => \"rgb(\" ++string_concat(\",\", [string_of_int(r), \
         string_of_int(g), string_of_int(b)]) ++ \")\"\n\
         | RGBA((r,g,b),a) => \"rgba(\" ++string_concat(\",\", \
         [string_of_int(r), string_of_int(g),string_of_int(b), \
         string_of_float(a)]) ++ \")\"\n\
         | HSL(h,s,l) => \"hsl(\" ++ string_concat(\",\", [string_of_float(h), \
         string_of_float(s), string_of_float(l)]) ++ \")\"\n\
         | HSLA((h,s,l),a) => \"hsla(\" ++ string_concat(\",\", \
         [string_of_float(h), string_of_float(s), string_of_float(l), \
         string_of_float(a)]) ++ \")\"\n\
         | Named(name) => name\n\
         | OKLCH(l,c,h) => \"oklch(\" ++ string_concat(\" \", \
         [string_of_int(l) ++\"%\", string_of_float(c), string_of_int(h)]) ++ \
         \")\"  \n\
         end in\n\n\
